import {cowCapacity,cowSupply} from './cow-state.js';
/** @param {import('./engine.js').State} state @param {string} type @param {string} [cowId] */
export function cowCareReason(state,type,cowId=''){const g=state.cow;if(!g?.visited||!g.barn)return 'cowNotVisited';const cap=cowCapacity(g);if(type==='feedCows')return cowSupply(g.feedTrough)>=cap.feedG?'cowFeedFull':g.feedStoreG+g.starterRation.feedG+g.recoveryRation.feedG<=0?'cowNoFeed':'';if(type==='waterCows')return cowSupply(g.waterTrough)>=cap.waterMl?'cowWaterFull':Math.floor(state.water*1000)+g.starterRation.waterMl+g.recoveryRation.waterMl<=0?'cowNoWater':'';if(type==='inspectCow')return g.cows.some(c=>c.id===cowId)?'':'cowMissing';if(type==='cleanCowBarn')return g.barn.cleanliness===100?'cowAlreadyClean':'';if(type==='cleanCowStand')return g.barn.standCleanliness===100?'cowAlreadyClean':'';if(type==='cleanCowCan')return g.barn.canCleanliness===100?'cowAlreadyClean':'';return 'invalidCowCommand';}
/** Source-tagged placement, never a gift into shared inventories. @param {import('./engine.js').State} state @param {import('./engine.js').Command} command @param {import('./engine.js').DomainEvent[]} events */
export function applyCowCare(state,command,events){const reason=cowCareReason(state,command.type,command.cowId);if(reason)return reason;const g=state.cow;if(!g?.barn)return 'cowNotVisited';const cap=cowCapacity(g);
 if(command.type==='feedCows'){let space=cap.feedG-cowSupply(g.feedTrough);const before=space;for(const source of /** @type {const} */(['recovery','starter'])){const ration=source==='starter'?g.starterRation:g.recoveryRation,n=Math.min(space,ration.feedG);ration.feedG-=n;g.feedTrough[source]+=n;space-=n;}const normal=Math.min(space,g.feedStoreG);g.feedStoreG-=normal;g.feedTrough.normal+=normal;space-=normal;g.stats.feedActions++;events.push({type:'cowFed',amount:before-space});return '';}
 if(command.type==='waterCows'){let space=cap.waterMl-cowSupply(g.waterTrough);const before=space;for(const source of /** @type {const} */(['recovery','starter'])){const ration=source==='starter'?g.starterRation:g.recoveryRation,n=Math.min(space,ration.waterMl);ration.waterMl-=n;g.waterTrough[source]+=n;space-=n;}const normal=Math.min(space,Math.floor(state.water*1000));state.water=Math.max(0,state.water-normal/1000);g.waterTrough.normal+=normal;g.stats.sharedWaterMl+=normal;space-=normal;g.stats.waterActions++;events.push({type:'cowWatered',amount:before-space});return '';}
 if(command.type==='cleanCowBarn'){g.barn.cleanliness=100;g.stats.barnCleaned++;events.push({type:'cowBarnCleaned'});return '';}
 if(command.type==='cleanCowStand'){g.barn.standCleanliness=100;g.stats.standCleaned++;events.push({type:'cowStandCleaned'});return '';}
 if(command.type==='cleanCowCan'){g.barn.canCleanliness=100;g.stats.canCleaned++;events.push({type:'cowCanCleaned'});return '';}
 if(command.type==='inspectCow'){g.stats.inspected++;if(command.cowId==='cow.starter.a')g.mission.inspectedA=true;events.push({type:'cowInspected'});return '';}
 return 'invalidCowCommand';
}
